using System.Text;
using System.Text.Json;
using ExtractorTester.Matching;
using ExtractorTester.Models;

namespace ExtractorTester.Tests;

// Port of tests/test_matcher.py and tests/test_tiers.py, plus a byte-parity theory over
// Fixtures/Matching/matcher_cases.json (generated by gen_matcher_fixtures.py from the Python matcher).
public sealed class MatchingTests
{
    // test_matcher.rec
    private static FileRecord Rec(string fid, string name, string family = "pdf", string? textHash = null, params FileRecord[] children) => new()
    {
        FileId = fid,
        ParentId = "P",
        Index = 0,
        Name = name,
        Mime = "application/pdf",
        Family = family,
        Path = name,
        Fields = [],
        Text = "",
        TextHash = textHash,
        DecodeErrors = 0,
        Children = [.. children],
        MissingFields = [],
    };

    private static FileRecord Rec(string fid, string name, params FileRecord[] children) => Rec(fid, name, "pdf", null, children);

    // test_tiers.rec
    private static FileRecord T(string fid, string name, long index = 0, string? textHash = null, string family = "pdf") =>
        Rec(fid, name, family, textHash) with { Index = index, Path = $"r/{name}" };

    private static Item Itm(string side, FileRecord root) =>
        new() { ItemId = "I", Side = side, Metadata = [], Files = [root], SourcePath = "" };

    private static List<(string, string?, string?, string?, string?)> Summary(List<FilePair> pairs) =>
        pairs.Select(p => (p.Kind, p.Old?.FileId, p.New?.FileId, p.Tier, p.UnmatchedReason)).ToList();

    private static List<(string?, string?, string)> Ids(List<FilePair> pairs) =>
        pairs.Select(p => (p.Old?.FileId, p.New?.FileId, p.TieBreak)).ToList();

    private static List<string> FileIds(List<FileRecord> recs) => recs.Select(r => r.FileId).ToList();

    private static List<FilePair> Match(FileRecord old, FileRecord @new, IReadOnlyList<IMatchTier>? tiers = null) =>
        Matcher.MatchItem(Itm("old", old), Itm("new", @new), tiers);

    // ---- test_matcher.py ----

    [Fact]
    public void RootsPairWithTierRoot()
    {
        var pairs = Match(Rec("O", "root.eml"), Rec("N", "other.eml"));
        Assert.Equal([("paired", "O", "N", "root", null)], Summary(pairs));
    }

    [Fact]
    public void ChildrenPairAndLeftoversHaveNoCandidate()
    {
        var old = Rec("O", "r", Rec("o1", "a"), Rec("o2", "b", "image"));
        var @new = Rec("N", "r", Rec("n1", "a"), Rec("n2", "c", "doc"));
        Assert.Equal(
            [
                ("paired", "O", "N", "root", null),
                ("paired", "o1", "n1", "name", null),
                ("only-in-old", "o2", null, null, "no-candidate"),
                ("only-in-new", null, "n2", null, "no-candidate"),
            ],
            Summary(Match(old, @new)));
    }

    [Fact]
    public void SameNameEmptyTextSiblingsPairByPosition()
    {
        var old = Rec("O", "r", Rec("o1", "img.png"), Rec("o2", "img.png"));
        var @new = Rec("N", "r", Rec("n1", "img.png"), Rec("n2", "img.png"));
        var pairs = Match(old, @new);
        Assert.Equal([("name", "position"), ("name", "position")], pairs.Skip(1).Select(p => (p.Tier, p.TieBreak)).ToList());
        Assert.Equal(
            [("paired", "o1", "n1", "name", null), ("paired", "o2", "n2", "name", null)],
            Summary(pairs).Skip(1).ToList());
    }

    [Fact]
    public void DescendantsOfUnpairedParentAreParentUnpaired()
    {
        var old = Rec("O", "r", Rec("o1", "a", "x", null, Rec("o11", "deep", Rec("o111", "deeper"))));
        var @new = Rec("N", "r", Rec("n1", "b", "y", null, Rec("n11", "deep")));
        Assert.Equal(
            [
                ("only-in-old", "o1", null, null, "no-candidate"),
                ("only-in-old", "o11", null, null, "parent-unpaired"),
                ("only-in-old", "o111", null, null, "parent-unpaired"),
                ("only-in-new", null, "n1", null, "no-candidate"),
                ("only-in-new", null, "n11", null, "parent-unpaired"),
            ],
            Summary(Match(old, @new)).Skip(1).ToList());
    }

    [Fact]
    public void PairedChildrenAreWalkedInTurn()
    {
        var old = Rec("O", "r", Rec("o1", "a", Rec("o11", "x")));
        var @new = Rec("N", "r", Rec("n1", "a", Rec("n11", "x")));
        Assert.Equal(("paired", "o11", "n11", "name", null), Summary(Match(old, @new))[2]);
    }

    /// <summary>Fake tier pairing the first child of each side.</summary>
    private sealed class FamilyFake : IMatchTier
    {
        public string Name => "type-family";

        public TierResult Pair(List<FileRecord> oldChildren, List<FileRecord> newChildren)
        {
            if (oldChildren.Count == 0 || newChildren.Count == 0) return new([], oldChildren, newChildren);
            var p = new FilePair { Kind = "paired", Old = oldChildren[0], New = newChildren[0], Tier = "type-family" };
            return new([p], oldChildren[1..], newChildren[1..]);
        }
    }

    [Fact]
    public void CustomTierListLabelsPairs()
    {
        var pairs = Match(Rec("O", "r", Rec("o1", "a")), Rec("N", "r", Rec("n1", "b")), [new NameTier(), new FamilyFake()]);
        Assert.Equal(("paired", "o1", "n1", "type-family", null), Summary(pairs)[1]);
    }

    [Fact]
    public void DefaultTiersOrder()
    {
        Assert.Equal(["name", "text-hash", "type-family"], Matcher.DefaultTiers().Select(t => t.Name).ToList());
    }

    [Fact]
    public void WorkedExample()
    {
        var old = Rec("O", "root.eml",
            Rec("o1", "invoice.pdf", textHash: "h"),
            Rec("o2", "image001.png", "image"),
            Rec("o3", "image001.png", "image"));
        var @new = Rec("N", "root.eml",
            Rec("n1", "Invoice 2026.pdf", textHash: "h"),
            Rec("n2", "image001.png", "image"),
            Rec("n3", "image001.png", "image"),
            Rec("n4", "logo.png", "image"));
        Assert.Equal(
            [
                ("paired", "O", "N", "root", null),
                ("paired", "o2", "n2", "name", null),
                ("paired", "o3", "n3", "name", null),
                ("paired", "o1", "n1", "text-hash", null),
                ("only-in-new", null, "n4", null, "no-candidate"),
            ],
            Summary(Match(old, @new)));
    }

    [Fact]
    public void MatchingDoesNotReferenceCompareOrRender()
    {
        // C# equal of test_matching_does_not_import_compare_or_render: the matcher source names no
        // Compare/Render namespace (one assembly, so module-import isolation is checked at source level).
        var dir = new DirectoryInfo(AppContext.BaseDirectory);
        while (dir is not null && !File.Exists(Path.Combine(dir.FullName, "ExtractorTester.sln"))) dir = dir.Parent;
        Assert.NotNull(dir);
        var src = File.ReadAllText(Path.Combine(dir.FullName, "src", "ExtractorTester", "Matching.cs"));
        Assert.DoesNotContain("ExtractorTester.Compare", src);
        Assert.DoesNotContain("ExtractorTester.Render", src);
    }

    // ---- test_tiers.py ----

    [Fact]
    public void NameTierIsAMatchTier()
    {
        IMatchTier tier = new NameTier();
        Assert.Equal("name", tier.Name);
    }

    [Fact]
    public void UniqueNamesPairWithoutTieBreak()
    {
        var (pairs, oldRest, newRest) = new NameTier().Pair(
            [T("o1", "a"), T("o2", "b")], [T("n1", "b"), T("n2", "a"), T("n3", "c")]);
        Assert.Equal([("o1", "n2", "none"), ("o2", "n1", "none")], Ids(pairs));
        Assert.All(pairs, p => Assert.True(p.Tier == "name" && p.Kind == "paired"));
        Assert.Empty(oldRest);
        Assert.Equal(["n3"], FileIds(newRest));
    }

    [Fact]
    public void NamesAreCaseSensitive()
    {
        var (pairs, oldRest, newRest) = new NameTier().Pair([T("o1", "A")], [T("n1", "a")]);
        Assert.Empty(pairs);
        Assert.Single(oldRest);
        Assert.Single(newRest);
    }

    [Fact]
    public void EmptyNamesNeverPair()
    {
        var (pairs, oldRest, newRest) = new NameTier().Pair([T("o1", "")], [T("n1", "")]);
        Assert.Empty(pairs);
        Assert.Equal(["o1"], FileIds(oldRest));
        Assert.Equal(["n1"], FileIds(newRest));
    }

    [Fact]
    public void SameNameEmptyTextPairsByPosition()
    {
        var pairs = new NameTier().Pair([T("o1", "x", 1), T("o2", "x", 2)], [T("n1", "x", 1), T("n2", "x", 2)]).Pairs;
        Assert.Equal([("o1", "n1", "position"), ("o2", "n2", "position")], Ids(pairs));
    }

    [Fact]
    public void SameNameTextHashBreaksTieBeforePosition()
    {
        var pairs = new NameTier().Pair(
            [T("o1", "x", textHash: "h1"), T("o2", "x", textHash: "h2")],
            [T("n1", "x", textHash: "h2"), T("n2", "x", textHash: "h1")]).Pairs;
        Assert.Equal([("o1", "n2", "text-hash"), ("o2", "n1", "text-hash")], Ids(pairs));
    }

    [Fact]
    public void HashTieBreakRequiresSameFamily()
    {
        var pairs = new NameTier().Pair(
            [T("o1", "x", textHash: "h", family: "pdf"), T("o2", "x")],
            [T("n1", "x"), T("n2", "x", textHash: "h", family: "image")]).Pairs;
        Assert.Equal([("o1", "n1", "position"), ("o2", "n2", "position")], Ids(pairs));
    }

    [Fact]
    public void ExtraSameNameFilesPassOnInOrder()
    {
        var (pairs, oldRest, newRest) = new NameTier().Pair(
            [T("o1", "x"), T("o2", "y")], [T("n1", "x"), T("n2", "z"), T("n3", "x"), T("n4", "x")]);
        Assert.Equal([("o1", "n1", "position")], Ids(pairs));
        Assert.Equal(["o2"], FileIds(oldRest));
        Assert.Equal(["n2", "n3", "n4"], FileIds(newRest));
    }

    [Fact]
    public void TextHashTierPairsUniqueHashAndFamily()
    {
        var (pairs, oldRest, newRest) = new TextHashTier().Pair(
            [T("o1", "a", textHash: "h"), T("o2", "b", textHash: "k")],
            [T("n1", "c", textHash: "k"), T("n2", "d", textHash: "z")]);
        Assert.Equal([("o2", "n1", "none")], Ids(pairs));
        Assert.Equal("text-hash", pairs[0].Tier);
        Assert.Equal(["o1"], FileIds(oldRest));
        Assert.Equal(["n2"], FileIds(newRest));
    }

    [Fact]
    public void TextHashTierNoneHashNeverPairs()
    {
        var (pairs, oldRest, newRest) = new TextHashTier().Pair([T("o1", "a")], [T("n1", "b")]);
        Assert.Empty(pairs);
        Assert.Single(oldRest);
        Assert.Single(newRest);
    }

    [Fact]
    public void TextHashTierRequiresSameFamily()
    {
        var pairs = new TextHashTier().Pair(
            [T("o1", "a", textHash: "h", family: "pdf")], [T("n1", "b", textHash: "h", family: "image")]).Pairs;
        Assert.Empty(pairs);
    }

    [Fact]
    public void TextHashTierAmbiguousNotPaired()
    {
        var (pairs, oldRest, newRest) = new TextHashTier().Pair(
            [T("o1", "a", textHash: "h"), T("o2", "b", textHash: "h")], [T("n1", "c", textHash: "h")]);
        Assert.Empty(pairs);
        Assert.Equal(2, oldRest.Count);
        Assert.Single(newRest);
    }

    [Fact]
    public void TypeFamilyTierPairsSinglePerFamily()
    {
        var (pairs, oldRest, newRest) = new TypeFamilyTier().Pair(
            [T("o1", "a", family: "pdf"), T("o2", "b", family: "image")],
            [T("n1", "c", family: "image"), T("n2", "d", family: "pdf")]);
        Assert.Equal([("o1", "n2", "none"), ("o2", "n1", "none")], Ids(pairs));
        Assert.All(pairs, p => Assert.Equal("type-family", p.Tier));
        Assert.Empty(oldRest);
        Assert.Empty(newRest);
    }

    [Fact]
    public void TypeFamilyTierTwoSameFamilyOnOneSideNotPaired()
    {
        var (pairs, oldRest, newRest) = new TypeFamilyTier().Pair([T("o1", "a"), T("o2", "b")], [T("n1", "c")]);
        Assert.Empty(pairs);
        Assert.Equal(["o1", "o2"], FileIds(oldRest));
        Assert.Equal(["n1"], FileIds(newRest));
    }

    // ---- FilePair JSON parity with the Python matcher ----

    private static readonly string FixturePath =
        Path.Combine(AppContext.BaseDirectory, "Fixtures", "Matching", "matcher_cases.json");

    public static IEnumerable<object[]> CaseNames()
    {
        using var doc = JsonDocument.Parse(File.ReadAllBytes(FixturePath));
        return doc.RootElement.EnumerateArray().Select(c => new object[] { c.GetProperty("name").GetString()! }).ToList();
    }

    [Theory]
    [MemberData(nameof(CaseNames))]
    public void FilePairJsonEqualsPython(string name)
    {
        using var doc = JsonDocument.Parse(Encoding.UTF8.GetString(File.ReadAllBytes(FixturePath)));
        var c = doc.RootElement.EnumerateArray().Single(e => e.GetProperty("name").GetString() == name);
        var tier = c.GetProperty("tier").GetString();
        var expected = c.GetProperty("pairs").EnumerateArray().Select(p => p.GetString()!).ToList();
        if (tier == "match")
        {
            var old = PyJson.Deserialize<Item>(c.GetProperty("old").GetString()!);
            var @new = PyJson.Deserialize<Item>(c.GetProperty("new").GetString()!);
            Assert.Equal(expected, Matcher.MatchItem(old, @new).Select(p => PyJson.Serialize(p)).ToList());
            return;
        }
        List<FileRecord> Recs(string side) =>
            c.GetProperty(side).EnumerateArray().Select(r => PyJson.Deserialize<FileRecord>(r.GetString()!)).ToList();
        IMatchTier t = Matcher.DefaultTiers().Single(x => x.Name == tier);
        var res = t.Pair(Recs("old"), Recs("new"));
        Assert.Equal(expected, res.Pairs.Select(p => PyJson.Serialize(p)).ToList());
        Assert.Equal(c.GetProperty("old_rest").EnumerateArray().Select(e => e.GetString()!).ToList(), FileIds(res.OldRest));
        Assert.Equal(c.GetProperty("new_rest").EnumerateArray().Select(e => e.GetString()!).ToList(), FileIds(res.NewRest));
    }
}
